import { KEYS, getObject, getJson, putObject, putJson } from "./store.mjs";
import { collectionUrl, now } from "./meta.mjs";
import { validateEncryptionDescriptor, assertDescriptorTransition } from "./epochs.mjs";
import { invalidRequestBody, preconditionFailed, revisionsImmutable } from "./problems.mjs";

// A Collection's governing history log (PWS v0.5, Collection Governing
// History Log): a client-written, append-only JSON Lines log stored at the
// `meta/log` sub-resource, from whose head entry the server derives the
// Collection's `encryption` member (and `revisions`, the one reserved slot).
// The server stores the log, checks the line contract and the head-state
// transition on every write, and derives; it verifies neither the entries'
// proofs nor their hash chain -- that is the governing profile's reader's
// job (PWS-EC's resource log profile).
//
// Stored as one object, `meta/{c}.log`, normalized to one entry per line
// with a trailing line feed, versioned by its own ETag. A log write also
// touches the Collection's metadata object, so the metadata ETag advances
// with the derived member, as the spec requires of `metaVersion`.

const isObject = (value) => typeof value === "object" && value !== null && !Array.isArray(value);

export const LOG_CONTENT_TYPE = "text/jsonl";

// The line contract: a non-empty body, every line a JSON object with an
// object `state`, blank lines only as the trailing line feed. Returns the
// lines (without their line feeds) and the parsed entries.
export function parseLog(body) {
  const text = Buffer.isBuffer(body) ? body.toString("utf8") : String(body ?? "");
  if (text.length === 0) {
    throw invalidRequestBody("The log body is empty.");
  }
  const raw = text.split("\n");
  if (raw[raw.length - 1] === "") {
    raw.pop();
  }
  if (raw.length === 0) {
    throw invalidRequestBody("The log body is empty.");
  }
  const entries = raw.map((line, i) => {
    let entry;
    try {
      entry = JSON.parse(line);
    } catch {
      throw invalidRequestBody(`Line ${i + 1} of the log is not a JSON object.`);
    }
    if (!isObject(entry)) {
      throw invalidRequestBody(`Line ${i + 1} of the log is not a JSON object.`);
    }
    if (!isObject(entry.state)) {
      throw invalidRequestBody(`Line ${i + 1} of the log carries no object "state".`);
    }
    return entry;
  });
  return { lines: raw, entries };
}

export const serializeLog = (lines) => lines.join("\n") + "\n";

// The stored log of a Collection, or null when it carries none.
export async function readCollectionLog(spaceId, collectionId) {
  const object = await getObject(spaceId, KEYS.collectionLog(collectionId));
  if (object === null) {
    return null;
  }
  const { lines, entries } = parseLog(object.body);
  return { text: object.body.toString("utf8"), lines, entries, etag: object.etag };
}

// The members the log governs, derived from its head entry: `encryption`
// is the head `state` with the `revisions` slot taken out and `history`
// stamped on; `revisions` is the slot, when present.
export function deriveGovernedMembers(req, spaceId, collectionId, entries) {
  const head = entries[entries.length - 1].state;
  const { revisions, ...descriptor } = head;
  const method = entries[0]?.parameters?.method;
  const encryption = {
    ...descriptor,
    ...(typeof method === "string" && {
      history: { method, resource: `${collectionUrl(req, spaceId, collectionId)}meta/log` },
    }),
  };
  return { encryption, ...(isObject(revisions) && { revisions }) };
}

// Applies the governed members to a stored Collection Metadata document,
// replacing any client-written `encryption` (which governance refuses, so
// none should be there). Returns the document unchanged when the
// Collection is not governed.
export async function withGovernedMembers(req, spaceId, collectionId, doc) {
  const log = await readCollectionLog(spaceId, collectionId);
  if (log === null) {
    return { doc, governed: false };
  }
  const derived = deriveGovernedMembers(req, spaceId, collectionId, log.entries);
  const { encryption: _encryption, revisions: _revisions, ...rest } = doc;
  return { doc: { ...rest, ...derived }, governed: true, log };
}

// What a verifying reader strips before comparing a served projection to
// the verified head: the one member the projection carries and an entry's
// state never does.
export function stripHistory(descriptor) {
  if (!isObject(descriptor)) {
    return descriptor;
  }
  const { history: _history, ...rest } = descriptor;
  return rest;
}

const validateRevisionsSlot = (revisions, pointer) => {
  if (revisions === undefined) {
    return;
  }
  if (!isObject(revisions)) {
    throw invalidRequestBody(`${pointer} must be an object.`);
  }
  if (revisions.immutable !== undefined && typeof revisions.immutable !== "boolean") {
    throw invalidRequestBody(`${pointer}/immutable must be a boolean.`);
  }
  if (revisions.resolution !== undefined && typeof revisions.resolution !== "string") {
    throw invalidRequestBody(`${pointer}/resolution must be a string.`);
  }
};

// The checks a log write runs on its head state: the descriptor shape (as
// a supplied descriptor is checked), the `revisions` slot's shape, and on
// an append the transition invariants against the prior head.
export function checkHeadState(entries, priorEntries) {
  const head = entries[entries.length - 1].state;
  const { revisions, ...descriptor } = head;
  validateEncryptionDescriptor(descriptor, "/state");
  validateRevisionsSlot(revisions, "/state/revisions");
  if (priorEntries) {
    const { revisions: priorRevisions, ...prior } = priorEntries[priorEntries.length - 1].state;
    assertDescriptorTransition(prior, descriptor);
    const before = priorRevisions ?? {};
    const after = revisions ?? {};
    if ((after.resolution ?? undefined) !== (before.resolution ?? undefined) || (after.immutable ?? false) !== (before.immutable ?? false)) {
      throw revisionsImmutable('"revisions.resolution" and "revisions.immutable" are set at the genesis entry and never change.');
    }
  }
}

// An append carries the stored lines verbatim followed by exactly one new
// line: a body the stored log is not a prefix of is a stale read (412),
// one that extends it by no line or several is malformed (400).
export function assertFastForward(storedLines, newLines) {
  for (let i = 0; i < storedLines.length; i++) {
    if (newLines[i] !== storedLines[i]) {
      throw preconditionFailed("The log body does not extend the stored log: it was read stale or rewritten.");
    }
  }
  if (newLines.length !== storedLines.length + 1) {
    throw invalidRequestBody(
      newLines.length <= storedLines.length
        ? "The log body appends no entry."
        : "The log body appends more than one entry; an append carries exactly one new line."
    );
  }
}

// Writes the normalized log under the given precondition; resolves to the
// new ETag.
export async function writeCollectionLog(spaceId, collectionId, lines, preconditions) {
  return putObject(spaceId, KEYS.collectionLog(collectionId), {
    body: Buffer.from(serializeLog(lines), "utf8"),
    contentType: LOG_CONTENT_TYPE,
    ...preconditions,
  });
}

// A log write changes the derived member, so the Collection's metadata
// object is rewritten with a fresh `updatedAt` and its ETag advances. The
// stored object never holds the derived member.
export async function touchCollectionMeta(spaceId, collectionId) {
  const stored = await getJson(spaceId, KEYS.collectionMeta(collectionId));
  if (stored === null) {
    return;
  }
  const { encryption: _encryption, revisions: _revisions, ...rest } = stored.doc;
  try {
    await putJson(spaceId, KEYS.collectionMeta(collectionId), { ...rest, updatedAt: now() }, { ifMatch: stored.etag });
  } catch (err) {
    // A concurrent metadata write already advanced the ETag
    if (err?.status !== 412) {
      throw err;
    }
  }
}
